import logging
from datetime import datetime
from enum import Enum
from typing import Any

from util.date_time_util import build_standard_utc_timestamp_str

logger = logging.getLogger()
logger.setLevel(logging.INFO)


class LogEventType(Enum):
    APIRequest = "api_request"
    APIResponse = "api_response"
    DynamoDBQuery = "dynamodb_query"
    DynamoDBPutItem = "dynamodb_put_item"
    DynamoDBUpdateItem = "dynamodb_update_item"
    DynamoDBException = "dynamodb_exception"


class Log:

    def __init__(self, data: Any, event_type: LogEventType):
        self.data = data
        self.event_type = event_type
        self.message = {
            "timestamp": build_standard_utc_timestamp_str(datetime.utcnow()),
            "log_type": "app_log",
            "event_type": event_type.value,
            "data": data,
        }

    def info(self):
        logger.info(self.message)

    def warning(self):
        logger.warning(self.message)

    def error(self):
        logger.error(self.message)

    def exception(self):
        logger.exception(self.message)
